<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require dirname(__DIR__).'/lib/analytics.php';require dirname(__DIR__).'/lib/repository.php';require dirname(__DIR__).'/lib/view.php';$pdo=db();$tab=(string)($_GET['tab']??'rakuten');public_header($pdo,'ランキング');?><h1>人気ランキング</h1><p><a class="pill" href="?tab=rakuten">楽天人気ランキング</a> <a class="pill" href="?tab=pinkclub">PinkClub内人気ランキング</a></p><?php if($tab==='pinkclub'){$items=search_items($pdo,['sort'=>'popular'],50,0);?><div class="grid"><?php foreach($items as $i)item_card($i);?></div><?php }else{$rows=$pdo->query('SELECT * FROM rakuten_rankings WHERE genre_id=0 ORDER BY rank_no LIMIT 50')->fetchAll();?><div class="grid"><?php foreach($rows as $r):?><article class="card"><a href="<?=h((string)($r['affiliate_url']?:$r['item_url']))?>" target="_blank" rel="nofollow sponsored noopener"><?php if($r['image_url']):?><img src="<?=h((string)$r['image_url'])?>" alt="<?=h((string)$r['item_name'])?>"><?php endif?><h3><?=number_format((int)$r['rank_no'])?>位 <?=h((string)$r['item_name'])?></h3><div class="price">¥<?=number_format((int)$r['item_price'])?></div><div class="rating">★ <?=number_format((float)$r['review_average'],2)?>（<?=number_format((int)$r['review_count'])?>件）</div></a></article><?php endforeach?></div><?php }render_analytics_beacon();public_footer();
